+            }
+            liq::Node::Raw { span, content } => out.push(ir::Node::RawBlock {
+                span: *span,
+                body: content.clone(),
+            }),
+            liq::Node::Comment { content, .. } => out.push(preserved_comment(content)),
+            liq::Node::InlineComment { text, .. } => out.push(preserved_comment(text)),
+            liq::Node::IfChanged { span, body } => {
