+            }
+            liq::Node::Unknown { span, name, .. } => {
+                self.report_only(
+                    *span,
+                    Severity::Residual,
+                    format!("unknown tag `{{% {name} %}}` — host-specific, needs a human"),
+                );
+                out.push(comment(&format!("unknown tag {name} — needs a human")));
