+/// The MaxBars comparison-operator head for a Liquid comparison.
+fn cmp_op(op: liq::CmpOp) -> &'static str {
+    match op {
+        liq::CmpOp::Eq => "eq",
+        liq::CmpOp::Ne => "ne",
+        liq::CmpOp::Gt => "gt",
+        liq::CmpOp::Lt => "lt",
+        liq::CmpOp::Ge => "gte",
+        liq::CmpOp::Le => "lte",
+        liq::CmpOp::Contains => "contains",
+    }
+}
