+/// Map a Liquid filter name to its MaxBars prelude helper (identity when there is no
+/// rename); unknown names pass through and are flagged at the call site.
+fn map_filter(name: &str) -> &str {
+    match name {
+        "upcase" => "uppercase",
+        "downcase" => "lowercase",
+        "size" => "count",
+        other => other,
+    }
+}
